{
  "assessment": "The M23/AFC rebellion backed by Rwanda continues to control Nord-Kivu and Sud-Kivu, presenting an existential threat to our territorial integrity and sovereignty. Our economic indicators remain relatively resilient, but the civil war in the east drains focus and stability. Mobilisation is active per our standing orders. We must reinforce our military posture, prepare to reclaim the occupied eastern regions, and maintain diplomatic pressure against external support for the insurgency.",
  "directives": [
    {
      "type": "military_deploy",
      "target": "RWA",
      "amount": 0,
      "sub": "",
      "regions": ["Nord-Kivu", "Sud-Kivu"],
      "order": "Deploy armed forces to the eastern border regions to counter M23 and deter Rwandan intervention."
    },
    {
      "type": "sanction",
      "target": "RWA",
      "amount": 1,
      "sub": "",
      "regions": [],
      "order": "Impose strict economic sanctions on Rwanda for backing armed insurgency within our borders."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 3.5,
      "sub": "military",
      "regions": [],
      "order": "Increase military expenditure to 3.5% of GDP to fund ongoing security operations in the east."
    },
    {
      "type": "repression_level",
      "target": null,
      "amount": 0.6,
      "sub": "",
      "regions": [],
      "order": "Increase security presence and law enforcement vigilance to prevent internal subversion."
    }
  ],
  "cables": [
    {
      "to": "RWA",
      "private": false,
      "text": "We demand an immediate cessation of all support for the M23 and AFC rebels operating within the sovereign territory of the Democratic Republic of the Congo. Continued aggression will be met with decisive measures."
    },
    {
      "to": "AGO",
      "private": true,
      "text": "We value our strong bilateral relations and seek closer regional cooperation and intelligence sharing to stabilize the Great Lakes region against destabilizing armed groups."
    }
  ],
  "public_statement": "The government of the Democratic Republic of the Congo remains steadfast in defending our national sovereignty and territorial integrity. We will pursue all necessary diplomatic and military means to liberate Nord-Kivu and Sud-Kivu from illegal armed groups and their foreign backers.",
  "standing_orders": [
    {
      "when": "at_war",
      "do": {
        "type": "military_mobilize",
        "target": null,
        "amount": 0.3,
        "sub": "",
        "order": "Maintain military mobilization to support operations in the east."
      }
    }
  ],
  "detailed_report": "military"
}
